bounded_host_request.command:
set -eu
gay="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])gaybbs([-_]|$)' || true)"
test "$(printf '%s\n' "$gay" | sed '/^$/d' | wc -l)" -eq 1 || { echo STK04_GROUP_CONTAINER_AMBIGUOUS; exit 61; }
docker exec -i "$gay" node --input-type=module - <<'NODE'
import fs from "node:fs";import https from "node:https";
const path=process.env.BOT_TOKEN_FILE;
if(!path||!path.startsWith("/"))throw Error("STK04_BOT_TOKEN_FILE_NOT_CONFIGURED");
const token=fs.readFileSync(path,"utf8").trim();
if(!/^[0-9]{7,15}:[A-Za-z0-9_-]{30,100}$/.test(token))throw Error("STK04_BOT_CREDENTIAL_INVALID");
function api(name,params){return new Promise((ok,bad)=>{
 const data=JSON.stringify(params);const req=https.request({
 hostname:"api.telegram.org",port:443,family:4,path:"/bot"+token+"/"+name,
 method:"POST",headers:{"Content-Type":"application/json","Content-Length":Buffer.byteLength(data)},timeout:12000
 },res=>{let txt="";res.on("data",c=>{if(txt.length<65536)txt+=c});res.on("end",()=>{
 try{const j=JSON.parse(txt);if(j.ok!==true)bad(Error("STK04_API_"+name+"_REJECTED_"+String(j.error_code||0)));else ok(j.result)}
 catch(e){bad(e)}
 });});req.on("timeout",()=>req.destroy(Error("STK04_TIMEOUT")));req.on("error",e=>bad(Error("STK04_NETWORK_"+String(e.code||"UNKNOWN"))));req.end(data);
});}
try{
 const me=await api("getMe",{});
 if(!me.is_bot||String(me.username).toLowerCase()!=="gaybbs_bot")throw Error("STK04_WRONG_BOT_IDENTITY");
 const chat=await api("getChat",{chat_id:-1002373696859});
 if(chat.type!=="supergroup"||chat.is_forum!==true||Number(chat.id)!==-1002373696859)throw Error("STK04_TARGET_FORUM_UNVERIFIED");
 const member=await api("getChatMember",{chat_id:-1002373696859,user_id:me.id});
 if(!["administrator","creator"].includes(member.status))throw Error("STK04_NOT_ADMINISTRATOR");
 if(member.status==="administrator"&&member.can_pin_messages!==true)throw Error("STK04_PIN_PERMISSION_DENIED");
 console.log("STK04_GROUP_BOT_AUTH=PASS");
 console.log("STK04_FORUM_ID_VERIFIED=PASS");
 console.log("STK04_BOT_PIN_PERMISSION=PASS");
}catch(e){console.error(String(e.message||"STK04_UNCLASSIFIED"));process.exitCode=1}
NODE
